(p/'tests/Support/BehaviorCases.php').write_text(r'''<?php

declare(strict_types=1);
namespace Tests\Support;
use Guard\Cli\Application;
use JsonException;
use RuntimeException;
/** Executes the CLI characterization scenarios captured before the refactor. */
final class BehaviorCases
{
    /** @return iterable<string, array{array{name: string, files: array<string, string>, commands: list<list<string>>}, list<array{exit: int, output: string, files: array<string, string>}>}> */
    public function scenarios(): iterable
    {
        $base = dirname(__DIR__) . '/Fixture/Behavior/';
        $source = file_get_contents($base . 'scenarios.json');
        $expectedSource = file_get_contents($base . 'expected.json');
        if ($source === false || $expectedSource === false) {
            throw new RuntimeException('Missing guard characterization fixtures.');
        }
        /** @var list<array{name: string, files: array<string, string>, commands: list<list<string>>}> $scenarios */
        $scenarios = json_decode($source, true, 512, JSON_THROW_ON_ERROR);
        /** @var array<string, list<array{exit: int, output: string, files: array<string, string>}>> $expected */
        $expected = json_decode($expectedSource, true, 512, JSON_THROW_ON_ERROR);
        foreach ($scenarios as $scenario) {
            yield $scenario['name'] => [$scenario, $expected[$scenario['name']]];
        }
    }
    /**
     * @param array{name: string, files: array<string, string>, commands: list<list<string>>} $scenario
     * @return list<array{exit: int, output: string, files: array<string, string>}>
     */
    public function run(array $scenario): array
    {
        $package = dirname(__DIR__, 2);
        $project = new Project($scenario['files']);
        $results = [];
        try {
            foreach ($scenario['commands'] as $command) {
                $output = '';
                $application = new Application($project->root, static function (string $text) use (&$output): void { $output .= $text; });
                $exit = $application->run($command);
                $results[] = ['exit' => $exit, 'output' => str_replace([$project->root, $package], ['<project>', '<package>'], $output), 'files' => $project->files()];
            }
        } finally {
            $project->remove();
        }
        return $results;
    }
}
''')
